def run_decl_axiom_checks(
    decls: list[str],
    *,
    lean_decls: dict[str, LeanDecl],
    repo_root: Path,
    lake: str,
) -> dict[str, DeclAxiomInfo]:
    """Run ``#print axioms`` on the given declarations, grouped by module."""
    grouped = group_decls_by_module(decls, lean_decls)
